<#
|==============================================================================>|
   Git-Hub Automatic Releaser by APoorv Verma [AP] on 4/22/2014 (rebuilt 2026)
|==============================================================================>|
      $) Tracks changes and uploads latest versions of codes
      $) Auto-Creation via gh CLI ? no IE automation, no password prompt
      $) Bootstrap mode scans GH repos and cross-matches $PShell root files
      $) SHA256 hex hashes, compile-aware, self-seeding
      $) Supports wildcard sources and nested compilations
|==============================================================================>|
#>
[CmdLetBinding(DefaultParameterSetName="None")]
param(
    [parameter(ParameterSetName="R",Position=0)][Switch]$Rebuild,
    [Switch]$AcceptAll,
    [parameter(ParameterSetName="R",Position=1)][Alias("Msg")]$Message,
    [Switch]$Bootstrap
)
# =======================================START=OF=COMPILER================================================================|
#    The Following Code was added by AP-Compiler 1.6 (APC: 1.3) To Make this program independent of AP-Core Engine
#    GitHub: https://github.com/avdaredevil/AP-Compiler
# ========================================================================================================================|
$Script:PSHell=$(if($PSHell){$PSHell}elseif($PSScriptRoot){$PSScriptRoot}else{"."});
if($AP_CONSOLE.mode -ne 'main' -or $AP_CONSOLE.customFlags.runAsCompiled) {
    $Script:AP_CONSOLE = [PsCustomObject]@{version=[version]'1.3'; mode = 'shim'; customFlags = @{}}
    function B64 {param([Parameter(ValueFromPipeline=$true)][String]$Text, [ValidateSet("UTF8","Unicode")][String]$Encoding = "UTF8")     [System.Text.Encoding]::$Encoding.GetString([System.Convert]::FromBase64String($Text))}
    # This syntax is to prevent AV's from misclassifying this as anything but innocuous
    & (Get-Alias iex) (B64 "")
} elseif($AP_CONSOLE.warnOnCompileRun) {& $AP_CONSOLE.warnOnCompileRun}
# ========================================END=OF=COMPILER=================================================================|
#++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
AP-Require "Internet" {Write-AP "!Need Internet To Function!";exit 1}
AP-Require "dep:git" {Write-AP "!Need git integrated To Function!";exit 1}
AP-Require "dep:gh" {Write-AP "!Need gh (GitHub CLI) To Function ? install: https://cli.github.com/";exit 1}
if (AP-Require "function:Load-GitIdentity") {Load-GitIdentity personal} # personal for open-source pushes
# Pre-flight LLM ping. Tiny ~1-token round-trip (<<$0.0001) lets every
# downstream prompt know whether AI-assisted suggestions are actually available,
# so we can branch with one boolean rather than re-probing at each call site.
# Silent on failure (missing key / net / API error) -- flag just stays $false.
$script:LlmAvailable = [bool](Run-LLMCall -UserPrompt "ok" -Temperature 0 -TimeoutSec 8)
if ($script:LlmAvailable) {Write-AP "+LLM online ? AI-assisted prompts enabled"}
#++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++++
$script:STACK_BKP = Backup-LocationStack
Push-Location $PSHell
$GitTemp = "$PSHell/$($isWindows ? '' : '.')Git-Temp"
$HashFile = "$GitTemp/Current-Versions.map"
$MapFile  = "$GitTemp/Git-Sources.map"
$PKGs = @{}

if (!(Test-Path $GitTemp)) {md $GitTemp >$null; if ($IsWindows) {attrib +h $GitTemp}}
if ($Rebuild -and (Test-Path $HashFile)) {Write-AP "!Rebuilding Git/AP Cache"; del $HashFile}

"Git-Sources","Current-Versions" | ? {!(Test-Path -type Leaf "$GitTemp/$_.map")} | % {
    Write-AP "*Creating new [$_] file"
    $hdr = if ($_ -eq "Current-Versions") {
        @("@    Version Tracking File for GitHub Projects in AP MGMT Console",
          "@    EXAMPLE:  <Tool>@<File>|<SHA256-hex>")
    } else {
        @("@    Mapping File for GitHub Projects in AP MGMT Console",
          "@    EXAMPLE:  [GitUser]/[GitRepo]|[Tool-Name]|[Src1;Src2;...]|[public|private]",
          "@    visibility is optional (defaults to public)")
    }
    (@("@ --------------------------------------------------------------------------|") + $hdr +
     @("@ --------------------------------------------------------------------------|")) | Out-File -Encoding utf8 "$GitTemp/$_.map"
}

function QUIT ([int]$Code = 0) {
    if (AP-Require "function:Load-GitIdentity") {Load-GitIdentity} # reset identity
    Restore-LocationStack $script:STACK_BKP
    exit $Code
}

function Read-Maps {
    $Script:Maps = @(); $Script:SrcMap = @{}; $i = 0
    [IO.File]::ReadAllLines($MapFile) | ? {$_ -and $_[0] -ne "@"} | ? {$_ -match "^(?<GitHub>[^\|]+)\|(?<Name>[^\|]+)\|(?<Sources>[^\|]+)(\|(?<Viz>\w+))?$"} | % {
        $vis = if ($Matches.Viz) {$Matches.Viz.trim().ToLower()} else {"public"}
        if ($vis -notin "public","private") {$vis = "public"}
        $Obj = [PSCustomObject]@{
            Name       = $Matches.Name.trim()
            GitHub     = $Matches.GitHub.trim()
            Dest       = $Matches.GitHub.trim() -replace "/","-"
            Visibility = $vis
            ToCopy     = $Matches.Sources.split(";").trim()
            Sources    = @()
        }
        $Obj.Sources = $Obj.ToCopy | % {
            $Root = Resolve-Path $PSHell
            $Full = Join-Path $Root $_
            # Wildcard branch comes first because Test-Path -PathType Leaf returns True
            # on a glob like 'AP-Components/*.ps1' (any one match is a leaf), which would
            # otherwise short-circuit and leave the literal pattern in Sources ? breaking
            # per-file hashing in Current-Versions.map.
            if ($_ -match '[\*\?\[\]]') {
                $matched = ls $Full -File -ea 0
                if (!$matched) {Write-AP "!No files matched wildcard: $_ for $($Obj.Name)"; Quit 2}
                return $matched | % {$_.FullName -replace "$([Regex]::escape($Root))[\\\/]",""}
            }
            if (!(Test-Path $Full)) {Write-AP "!Missing source file: $_ for $($Obj.Name)"; Quit 2}
            if (Test-Path -PathType Leaf $Full) {return $_}
            ls $Full -R -File | % {$_.FullName -replace "$([Regex]::escape($Root))[\\\/]",""}
        } | % {$_}
        $Script:Maps += ,$Obj
        $Obj.Sources | % {$Script:SrcMap[$_] = $i}
        $i++
    }
}

function Read-Hashes {
    $Script:Hash = @{}
    [IO.File]::ReadAllLines($HashFile) | ? {$_ -and $_[0] -ne "@"} | ? {$_ -match "^(?<K>[^\|]+)\|(?<H>[A-Fa-f0-9]{32,})$"} | % {$Script:Hash[$Matches.K] = $Matches.H.ToUpper()}
}
function Write-Hashes {
    $hdr = [IO.File]::ReadAllLines($HashFile) | ? {$_ -and $_[0] -eq "@"}
    $body = $Script:Hash.Keys | Sort-Object | % {"$_|$($Script:Hash[$_])"}
    ($hdr + $body) | Out-File -Encoding utf8 $HashFile
}
function Compute-Hash ($Path) {(Get-FileHash -Algorithm SHA256 $Path).Hash}
function Hash-Key ($Entry, $File) {"$($Entry.Name)@$File"}
function Get-Destination ($Entry, $File) {Join-Path $GitTemp $Entry.Dest $File}

function Handle-Change ($Entry, $File) {
    $PKGs[$Entry.Name] = $Entry.Dest
    $src = Join-Path $PSHell $File
    $dst = Get-Destination $Entry (Split-Path $File)
    $h = Compute-Hash $src
    Write-AP "+Copying delta [$($Entry.Dest)\$File] -> $($h.Substring(0,8))...$($h.Substring($h.Length-8))"
    md $dst -ea 0 | Out-Null
    AP-Compile $src $dst
    $Script:Hash[(Hash-Key $Entry $File)] = $h
}

function GIT-SELF-AWARE ([String]$Folder) {
    Push-Location $Folder
    try {
        $f = (ls *.* -ex "readme.md",".gitignore" | ? name -notmatch "^\." | Get-Random).Name
        if (!$f) {Write-Host; return Write-APL ">-","Could not bind folder to a project"}
        $Data = try {$Maps[$SrcMap[$f]]} catch {}
        if (!$Data) {Write-Host; return Write-APL ">-","Could not resolve project from file ","!$f"}
        $repo = $Data.GitHub
        $exists = gh repo view $repo --json name --jq .name 2>$null

        # Fast-path: if the repo is fully set up (git init done, remote exists, LICENSE +
        # README present) and the workspace is clean + not ahead, append a quiet inline
        # ": no changes" to the caller's "Running git sync for [X]" header line (which
        # was started with no-newline) and bail ? skips the push prompt entirely.
        if ($exists -and (Test-Path ".git") -and (Test-Path LICENSE) -and (Test-Path README.md)) {
            $stat = git status | Out-String
            if ($stat -match "nothing to commit" -and $stat -notmatch "ahead of") {
                return Write-APL -NS "*: ","#$(col i)no changes$(col rS)"
            }
        }

        # From here on we'll print at least one follow-up line ? terminate the header.
        Write-Host

        if (!(Test-Path ".git")) {Write-AP ">*Initializing git for [$($Data.Name)]"; $null = git init -q}

        # If remote exists but our staging dir lacks a README/LICENSE, pull them
        if ($exists -and (!(Test-Path LICENSE) -or !(Test-Path README.md))) {
            Write-AP ">*Pulling README/LICENSE from [$repo]"
            rm tt -re -fo -ea 0
            gh repo clone $repo tt -- -q 2>&1 | Out-Null
            rm .git -re -fo -ea 0
            ls tt -Force | % {mv $_.FullName . -ea 0}
            rm tt -re -fo -ea 0
        }
        if (!(Test-Path LICENSE)) {
            Write-AP ">*Writing MIT LICENSE"
            gh api licenses/mit --jq .body | Out-File -Encoding utf8 LICENSE
        }
        if (!(Test-Path README.md)) {
            Write-AP ">*Creating README for [$($Data.Name)]"
            $drafted = $false
            if ($script:LlmAvailable) {
                $ans = Input-PromptWithFallback (Tab-Text "Draft full README via LLM?" 2) "y"
                if (Is-Affirmative $ans) {
                    Write-AP ">#Asking LLM to draft README.md..."
                    $srcFile = $Data.Sources[0]
                    $srcText = Get-Content (Join-Path $PSHell $srcFile) -Raw -ea 0
                    # Cap source at ~8k chars so we stay well within any chat-model
                    # context window without paying for the whole file on big scripts.
                    if ($srcText.Length -gt 8000) {$srcText = $srcText.Substring(0, 8000) + "`n[... truncated for prompt size ...]"}
                    $sys = @'
You write GitHub READMEs for AP's PowerShell scripts. Match this exact structure, NOTHING extra:

# <Project Name>
> <one-line description, noun-phrase or imperative, <= 120 chars, no trailing period>

## Usage
>
```PowerShell
.\<ScriptName>.ps1 [-Flag1] [-Flag2 <value>]
```
- <key usage note>
- <another if relevant>

## Features
>
- <feature>
- <feature>
- <4 to 8 bullets total>

Rules:
- Derive the Usage flags from the script's param() block.
- Derive Features from what the script actually does (read the source carefully).
- No fluff like "A script that...". Lead with verbs or noun-phrases.
- Never mention the AI, this prompt, or yourself.
- Output only the markdown. No surrounding code fences. No commentary.
'@
                    $user = "Project name: $($Data.Name)`nSource file: $srcFile`n---`n$srcText"
                    $draft = Run-LLMCall -SystemPrompt $sys -UserPrompt $user -Temperature 0.3 -TimeoutSec 60
                    # Strip a wrapping ```markdown ... ``` fence if the model ignored the rule.
                    if ($draft -match "^``````\w*\r?\n([\s\S]*)\r?\n``````$") {$draft = $Matches[1]}
                    if ($draft) {
                        $draft | Out-File -Encoding utf8 README.md
                        Write-AP "+Drafted README.md ($($draft.Length) chars). Edit before push if needed."
                        $drafted = $true
                    } else {Write-AP "-LLM draft failed ? falling back to manual prompt"}
                }
            }
            if (!$drafted) {
                $desc = Input-PromptWithFallback (Tab-Text "Description" 2) "$($Data.Name) by AP"
                "# $($Data.Name)","> $desc","" | Out-File -Encoding utf8 README.md
            }
        }

        if (!$exists) {
            Write-AP ">*Creating GitHub repo [$repo] as $($Data.Visibility)"
            # First non-title content line of README becomes the repo description. Strip
            # `=` underlines, `#` markdown titles, blockquote `>` prefixes, and backticks/pipes
            # that would trip up the gh CLI description flag.
            # (Use Get-Content ? [IO.File]::* resolves relative paths against the .NET CWD,
            # not PowerShell's Push-Location'd $PWD, and crashes when run from another dir.)
            $desc = (Get-Content README.md | ? {$_.trim() -and $_ -notmatch "^[=#]" -and $_ -ne $Data.Name} |
                     select -f 1) -replace '^>\s*','' -replace '[`|]'
            gh repo create $repo "--$($Data.Visibility)" --description (JS-OR $desc "$($Data.Name) by AP") --source . --remote origin 2>&1 | Out-Null
            if (!$?) {return Write-APL ">-","gh repo create failed for ","!$repo"}
            git add LICENSE *.md 2>$null
            git commit -q -m "AP-GitHub Releaser initial commit" 2>$null
            git push -q --set-upstream origin HEAD 2>&1 | Out-Null
            return Write-APL ">+","Created and pushed [$($Data.Name)]"
        }

        if (!((git remote -v) -match "^origin")) {git remote add origin "git@github.com:$repo.git"}

        # Short-circuit when there's genuinely nothing to do, BEFORE asking to push.
        # Run status without staging first ? untracked/modified/ahead states all show up
        # in `git status`, so a clean+not-ahead repo is the only early-return case.
        $stat = git status | Out-String
        if ($stat -match "nothing to commit" -and $stat -notmatch "ahead of") {return Write-APL ">#","No changes for [$($Data.Name)]"}

        if (!$AcceptAll) {
            [Console]::ForegroundColor = "Yellow"
            $inp = Input-Prompt (Tab-text "Push [$($Data.Name)] to GitHub? " 2)
            if (!(Is-Affirmative $inp)) {return}
        }
        $null = git add . 2>$null
        $msg = $Message
        if (!$msg) {
            # Show the full staged diff (we already ran `git add .` above so --cached covers new files too).
            # --text forces a textual diff even for files git labels "binary" ? UTF-16 .ps1 files have NUL bytes
            # between ASCII chars, which git's default heuristic flags as binary. They're not.
            $diff = git diff --cached --text | Out-String
            # Truncate each diff line to the terminal width (minus the ">#" prefix =
            # 4-space indent + "[#] " sign = 8 chars) so UTF-16 source files or minified
            # lines don't wrap into an unreadable wall.
            $w = try {[Console]::BufferWidth - 8} catch {120}
            $diff -split "`n" | % {
                $line = $_
                if ($line.Length -gt $w) {$line = $line.Substring(0, $w - 1) + "?"}
                Write-APL ">#$line"
            }

            # Pull the last 5 commits from this repo so the LLM can mirror AP's voice ?
            # capitalisation, backticks around code identifiers, bullet formatting, etc.
            $recent = git log -n 5 --format="=== %s%n%b" 2>$null | Out-String
            $styleRef = if ($recent.Trim()) {"`n`nRecent commits from this repo (match this voice and format):`n$recent"} else {""}

            # System prompt baked from AP's `commit` custom command rules: capitalised
            # imperative mood, backticks around code identifiers, no ticket/category
            # prefixes, optional bullets when there are multiple semantic changes.
            $sys = (dedent @'
                You write git commit messages for AP's personal PowerShell scripts.

                Style rules (match AP's voice):
                - Start with a capital letter in imperative mood ("Fix X", "Add Y", "Refactor Z").
                - Wrap code identifiers in single backticks ? function names, parameter flags (`-Fix`), file names (`README.md`), variable names (`$desc`).
                - NO ticket tags (never `[RES-1234]`, `[DES-xxx]`).
                - NO category prefixes (never `[UX]`, `[BUG]`, `[DOC]` ? those belong on PR titles, not commits).
                - NO trailing period on the summary line.

                Format:
                - Single semantic change ? one-line summary only (<= 72 chars when possible).
                - Multiple distinct changes ? summary line, blank line, then a bulleted list:

                    Brief summary of the collective change

                    - Detailed description of one semantically meaningful change
                    - Detailed description of another
                    - (up to ~14 bullets; only bullet when there are genuinely separable changes)

                Output only the commit message text ? no quotes, no code fences, no preamble.
'@) -join "`n"
            # Cap diff at ~12k chars so we stay within any chat-model context window
            # without paying for the full file on big rewrites. Style ref is small.
            $diffForPrompt = if ($diff.Length -gt 12000) {$diff.Substring(0, 12000) + "`n[... truncated for prompt size ...]"} else {$diff}
            $user = "git diff:`n$diffForPrompt$styleRef"
            $suggestion = Run-LLMCall -SystemPrompt $sys -UserPrompt $user
            $fallback = JS-OR $suggestion "Updated code"
            $msg = Input-PromptWithFallback (Tab-Text "Commit message" 2) $fallback
        }
        $branch = git remote show origin | ? {$_ -match "HEAD branch"} | % {$_ -replace ".*: ",""}
        $out = @()
        $out += git pull origin $branch 2>&1
        $out += git commit -a -m $msg 2>&1
        $out += git push --set-upstream origin $branch 2>&1
        if ($out -match "failed|rejected|conflict") {$out | % {Write-APL ">-$_"}}
        else {Write-APL ">+","Pushed [$($Data.Name)]"}
    } finally {Pop-Location}
}

function Bootstrap-Discover {
    $owner = JS-OR (@($Script:Maps | % {($_.GitHub -split '/')[0]}) | select -f 1) "avdaredevil"
    Write-AP "*Scanning PowerShell repos on github.com/$owner..."
    $gh = gh repo list $owner --limit 200 --json name,description,primaryLanguage,visibility,isFork 2>$null | ConvertFrom-Json
    if (!$gh) {return Write-AP "-Failed to fetch repo list from GitHub (is `gh auth status` clean?)"}
    $mapped = $Script:Maps | % {($_.GitHub -split '/')[1]}
    $psRepos = $gh | ? {!$_.isFork -and $_.primaryLanguage.name -eq 'PowerShell' -and $_.name -notin $mapped}
    $localFiles = ls $PSHell -File -Filter *.ps1 | % BaseName

    $norm = {param($s) ($s -replace '[-_.]','').ToLower()}
    $proposals = $psRepos | % {
        $r = $_
        $match = JS-OR ($localFiles | ? {$_ -eq $r.name} | select -f 1) ($localFiles | ? {(& $norm $_) -eq (& $norm $r.name)} | select -f 1)
        if ($match) {[PSCustomObject]@{Repo=$r.name; File="$match.ps1"; Viz=$r.visibility.ToLower(); Desc=$r.description}}
    } | ? {$_}

    if (!$proposals) {Write-AP "*No new match candidates found"}
    else {
        Write-AP "*Found $($proposals.Count) candidate(s). Confirm each:"
        $added = @()
        foreach ($p in $proposals) {
            Write-APL "  ","!$($p.Repo)"," ? ","+$($p.File)"," ","#($($p.Viz), $(JS-OR $p.Desc '(no description)'))"
            $ans = ?: $AcceptAll "y" {Input-Prompt (Tab-text "Add? [Y/n/q] " 2)}  # lazy ? don't prompt under -AcceptAll
            if ($ans -match "^q") {break}
            if ($ans -match "^n") {continue}
            Add-Content $MapFile "$owner/$($p.Repo)|$($p.Repo)|$($p.File)|$($p.Viz)"
            $added += $p.Repo
        }
        if ($added) {Write-AP "+Added $($added.Count) mapping(s): $($added -join ', ')"}
    }

    # Reload + seed Current-Versions.map with current hashes of ALL mapped files
    Read-Maps
    Write-AP "*Seeding Current-Versions.map with SHA256 hashes of all mapped sources..."
    $Script:Hash = @{}
    foreach ($Entry in $Script:Maps) {
        foreach ($File in $Entry.Sources) {
            $src = Join-Path $PSHell $File
            if (!(Test-Path $src)) {continue}
            $Script:Hash[(Hash-Key $Entry $File)] = Compute-Hash $src
        }
    }
    Write-Hashes
    Write-AP "+Seeded $($Script:Hash.Count) hash entries. Next plain run should be a no-op."
}

Read-Maps
Read-Hashes
$Global:MM = $Script:Maps

if ($Bootstrap) {Bootstrap-Discover; QUIT}

foreach ($Entry in $Script:Maps) {
    $NewFold = "$GitTemp/$($Entry.Dest)"
    if (!(Test-Path -Type Container $NewFold)) {Write-AP "*Creating folder for [$($Entry.Name)]"; md $NewFold | Out-Null}
    foreach ($FileOrFolder in $Entry.ToCopy) {
        if (Test-Path -type leaf $FileOrFolder) {continue}       # files handled below
        if (Test-Path -type Container $NewFold) {continue}       # folder already copied
        cp $FileOrFolder $NewFold -Force -Recurse
    }
    foreach ($File in $Entry.Sources) {
        $src = Join-Path $PSHell $File
        $new = Join-Path $NewFold $File
        $curr = Compute-Hash $src
        $old = $Script:Hash[(Hash-Key $Entry $File)]
        if (!$old) {Write-AP "*Creating hash entry for [$File]"; Handle-Change $Entry $File; continue}
        if (!(Test-Path -Type leaf $new)) {Write-AP "*Indexing [$File] for git configurations"; Handle-Change $Entry $File; continue}
        if ($old -ne $curr) {Write-AP "*Detected hash mismatch for [$File]"; Handle-Change $Entry $File}
    }
}

@($PKGs.Keys) | % {Write-AP "x*Running git sync for [$_]"; GIT-SELF-AWARE "$GitTemp/$($PKGs[$_])"}
Write-Hashes
QUIT
